import java.nio.file.Files
import java.nio.file.Path

fun bad(path: Path): ByteArray {
    return Files.readAllBytes(path) // bad
}

import java.nio.file.Files
import java.nio.file.Path

fun bad(path: Path): List<String> {
    return Files.readAllLines(path) // bad
}

import java.nio.file.Files
import java.nio.file.Path

fun bad(path: Path): String {
    return Files.readString(path) // bad
}

import java.io.InputStream

class Foo {
    fun bad(input: InputStream): ByteArray {
        return input.readAllBytes() // bad
    }
}

import java.io.ByteArrayOutputStream
import java.io.InputStream

class Foo {
    fun bad(input: InputStream): ByteArray {
        val baos = ByteArrayOutputStream()
        return baos.toByteArray() // bad
    }
}

import java.nio.file.Files
import java.nio.file.Path

fun good(path: Path) {
    Files.newInputStream(path).use { stream ->
        stream.copyTo(System.out) // streaming OK
    }
}

import java.io.InputStream
import org.apache.commons.io.IOUtils

class Foo {
    fun bad(input: InputStream): ByteArray = IOUtils.toByteArray(input) // bad
}
